import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
def read(p): return json.loads((ROOT/p).read_text(encoding='utf-8-sig'))
def write(p,v): (ROOT/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
at='2026-11-07'
lib=read('audit/source-notes.json')
def src(key,url,locator,evidence,topic,changing=False,limitations='Primary institutional text inspected; no film playback claimed.'):
    lib['sources']['b12-'+key]=dict(url=url,locator=locator,evidence=evidence,checkedBy='Codex',checkedAt=at,timeSensitive=changing,nextReviewAt='2027-02-04' if changing else None,limitations=limitations,topics=[topic])

