    for r in template['reviews']:
        s,p,rs,c,d,b,changing=data[r['questionId']]
        ss=[('b12-'+x) if 'b12-'+x in lib['sources'] else x for x in s];checked.update(ss)
        r.update(checks=['singleAnswer','context','wording','noGiveaway','distinctFact','category','difficulty','scope'],notes=d+' Final mobile wording, answer parallelism, category, editorial difficulty and theatrical scope checked.',context='Exact original film/version or historical event as worded; current park location only where explicitly marked time-sensitive.',timeSensitive=changing,nextReviewAt='2027-02-04' if changing else None)
        r['premise']=dict(reason=p,sources=ss)
        r['options']=[dict(basis=(b[n] if b else ('direct' if n==0 else 'exclusive-inference')),reason=reason,sources=ss) for n,reason in enumerate(rs)]
        r['challenge']=dict(reviewer='Codex',at=at,premiseChecked=True,alternativesExcluded=True,notes=c)
